"""Emit synthetic JSON lines for the Kafka to Log Analytics demo."""
import argparse
from datetime import datetime, timezone
import json
import sys
import time
import uuid


def non_negative(value):
    number = int(value)
    if number < 0:
        raise argparse.ArgumentTypeError("must be non-negative")
    return number


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--count", type=non_negative, default=100)
    parser.add_argument("--run-id", default="run-" + uuid.uuid4().hex[:12])
    parser.add_argument("--mode", choices=["normal", "error-spike"], default="normal")
    parser.add_argument("--message-bytes", type=non_negative, default=0,
                        help="Minimum ASCII message length; use 16000 to demonstrate byte chunking")
    parser.add_argument("--interval-ms", type=non_negative, default=0)
    args = parser.parse_args()
    print("demo_run_id=" + args.run_id, file=sys.stderr)
    for index in range(args.count):
        level = "ERROR" if index % (2 if args.mode == "error-spike" else 20) == 0 else "INFO"
        message = "Payment request failed" if level == "ERROR" else "Request completed"
        message = message.ljust(args.message_bytes, "x")
        event = {
            "timestamp": datetime.now(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z"),
            "demo_run_id": args.run_id,
            "event_id": f"{args.run_id}-{index:06d}",
            "service": ["checkout", "inventory", "payments"][index % 3],
            "level": level,
            "message": message,
            "latency_ms": 850 if level == "ERROR" else 25 + index % 50,
        }
        print(json.dumps(event, ensure_ascii=False, separators=(",", ":")), flush=True)
        if args.interval_ms:
            time.sleep(args.interval_ms / 1000)


if __name__ == "__main__":
    try:
        main()
    except BrokenPipeError:
        sys.exit(1)
